import{z as B,x as A,o as s,c as d,q as n,j as i,D as e,d as t,s as l,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"故障模型","description":"","frontmatter":{"title":"故障模型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/failure-models.md","filePath":"cs/failure-models.md","lastUpdated":1791063341000}'),p={name:"cs/failure-models.md"};function m(f,a,C,u,D,F){const r=A("Mermaid");return s(),d("div",null,[a[2]||(a[2]=n('<h1 id="故障模型" tabindex="-1">故障模型 <a class="header-anchor" href="#故障模型" aria-label="Permalink to &quot;故障模型&quot;">​</a></h1><div class="epigraph"><p>分布式算法的正确性只相对声明的故障类成立：崩溃停、崩溃恢复、漏发、拜占庭。模型弱一分，可证明的保证就少一分。</p><footer>—— 据 Lynch, Distributed Algorithms, 1996；Cristian, Understanding Fault-Tolerant Distributed Systems, CACM 1991 整理</footer></div><p><a href="/cs/db-audit">上一课</a>把数据库进阶收到审计与责任。<a href="/cs/proof-assistants">证明助手</a>已把「正确」收成可检查的项，本课不重开类型论，也不重写事务 ACID。缺口是<strong>进程与信道会坏</strong>：没有故障类，后面的时钟、检测器、共识都没有前提。后课默认已经读完本课：谈到容错，先问崩溃还是拜占庭、停机还是恢复。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单机课把崩溃当成进程结束；分布式里「对方没回」可能是慢、丢包、或已经死。缺口不是再列 errno，而是把行为收成<strong>可组合的对手</strong>：</p><ul><li><strong>崩溃停（crash-stop）</strong>：故障进程从此不再发消息，也不执行步骤。</li><li><strong>崩溃恢复（crash-recovery）</strong>：可以带着稳定存储回来，易失状态丢失。</li><li><strong>漏发（omission）</strong>：该发的没发或该收的没收，进程本身还在跑。</li><li><strong>拜占庭（Byzantine）</strong>：任意偏离协议，包括撒谎与合谋。后课才展开。</li></ul><p>信道可以可靠、公平丢失、或完全由对手调度。Lynch 的 I/O 自动机把进程与信道都写成带故障动作的自动机；本课只要这张分类表。<span class="marginnote">直觉类比：把对手想成员工——崩溃停是辞职后再也不来；漏发是人来上班但邮件常丢；崩溃恢复是离职又回来、还失忆了；拜占庭是会伪造老板签字的内鬼。对手越强，防它的协议越贵。</span></p><p><span class="marginnote">Cristian 1991 把故障按「能做什么」分层，而不是按硬件零件。崩溃是拜占庭的真子集：能证的拜占庭协议在崩溃下仍对，反过来不成立。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写规格时先钉故障类，再钉时间模型（下一课）。算法的「容忍 \\(f\\) 个故障」是相对于该类：\\(n=2f+1\\) 的崩溃共识与 \\(n=3f+1\\) 的拜占庭共识不是同一不等式。稳定存储把崩溃停改成崩溃恢复：恢复后必须用日志或纪元拒绝过期消息。</p>',10)),(s(),i(o,null,{default:e(()=>[l(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22%E7%AE%97%E6%B3%95%E8%A7%84%E6%A0%BC%22%5D%20--%3E%20FM%5B%22%E6%95%85%E9%9A%9C%E7%B1%BB%22%5D%0A%20%20SPEC%20--%3E%20TM%5B%22%E6%97%B6%E9%97%B4%E6%A8%A1%E5%9E%8B%20%E5%90%8E%E8%AF%BE%22%5D%0A%20%20FM%20--%3E%20CS%5B%22%E5%B4%A9%E6%BA%83%E5%81%9C%22%5D%0A%20%20FM%20--%3E%20CR%5B%22%E5%B4%A9%E6%BA%83%E6%81%A2%E5%A4%8D%22%5D%0A%20%20FM%20--%3E%20OM%5B%22%E6%BC%8F%E5%8F%91%22%5D%0A%20%20FM%20--%3E%20BY%5B%22%E6%8B%9C%E5%8D%A0%E5%BA%AD%20%E5%90%8E%E8%AF%BE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"不要把「网络分区」写成第五种进程故障：分区是信道连通性的对手，进程可能都还活着。后课 CAP 会用到这一点。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[t("崩溃停最利于证明：故障进程退出全局状态。实现上超时把「可能死了」当成崩溃，于是"),E("strong",null,"错误怀疑"),t("会把活进程当死——那是"),E("a",{href:"/cs/failure-detectors"},"故障检测器"),t("的缺口，本课只声明：检测不是模型的一部分，模型是真实行为。漏发可以模拟长时间不回，与异步调度叠在一起时，外部观察与崩溃停不可分。拜占庭包含漏发与崩溃，还包含伪造：认证信道（数字签名）可以把「任意」收成「对称」或「能验身份」。")],-1)),a[6]||(a[6]=E("p",null,"恢复：进程带着磁盘回来，但内存里的 ballot、term 丢了。协议必须把决策写进稳定存储，否则恢复节点可以改口，把崩溃停证明作废。",-1)),(s(),i(o,null,{default:e(()=>[l(r,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%AE%B9%E5%BF%8D%20f%20%E4%B8%AA%E6%95%85%E9%9A%9C%EF%BC%8C%E5%90%84%E8%A6%81%E5%A4%9A%E5%B0%91%E8%8A%82%E7%82%B9%EF%BC%9F%22%5D%20--%3E%20CS%5B%22%E5%B4%A9%E6%BA%83%E5%81%9C%E5%85%B1%E8%AF%86%EF%BC%9An%20%3D%202f%2B1%22%5D%0A%20%20Q%20--%3E%20BZ%5B%22%E6%8B%9C%E5%8D%A0%E5%BA%AD%E5%85%B1%E8%AF%86%EF%BC%9An%20%3D%203f%2B1%22%5D%0A%20%20CS%20--%3E%20E1%5B%22f%3D1%EF%BC%9A3%20%E5%8F%B0%E5%B0%B1%E5%A4%9F%22%5D%0A%20%20BZ%20--%3E%20E2%5B%22f%3D1%EF%BC%9A%E8%A6%81%204%20%E5%8F%B0%E8%B5%B7%22%5D%0A%20%20BZ%20--%3E%20WHY%7B%22%E4%B8%BA%E4%BD%95%E6%9B%B4%E8%B4%B5%EF%BC%9F%22%7D%0A%20%20WHY%20--%3E%20A%5B%22%E5%9D%8F%E8%8A%82%E7%82%B9%E4%B8%8D%E5%8F%AA%E6%B6%88%E5%A4%B1%EF%BC%8C%E8%BF%98%E4%BC%9A%E6%8A%95%E5%81%87%E7%A5%A8%EF%BC%8C%E8%AF%9A%E5%AE%9E%E5%A4%9A%E6%95%B0%E5%BF%85%E9%A1%BB%E5%8E%8B%E8%BF%87%E8%B0%8E%E7%A5%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">数字实例：\\(f=1\\) 时崩溃停 \\(n=2\\times1+1=3\\) 台，拜占庭 \\(n=3\\times1+1=4\\) 台；到 \\(f=5\\) 就是 11 台对 16 台。同一句「容忍 5 个故障」，在两种模型下是完全不同的集群预算。</span></p><p>本课不把数据库的介质故障、操作系统的内核 panic 再讲一遍：那些在单机栈已经是崩溃。分布式课要的是<strong>对其他节点可见的行为类</strong>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 FLP，不引入部分同步，不写拜占庭将军的口头/书面协议。不把云厂商的 SLA 当成故障模型。后课默认：进程故障先按崩溃停思考，需要磁盘回来再升级到崩溃恢复；任意恶意放到拜占庭课。时间假设下一课才加。</p><p>故障类是对手的语言，不是监控仪表盘上的红点。没有这类声明，后面每一条「多数派」都没有分母。<span class="marginnote">常见误区：初学者容易把「网络分区」当成第五种进程故障；分区是信道断了，两端进程可能都活得好好的。所以「进程会怎么坏」（故障类）与「消息怎么传」（信道模型）必须分开声明，混为一谈会推错协议。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>崩溃停、崩溃恢复、漏发、拜占庭是递增强的对手。</li><li>「容忍 \\(f\\)」相对故障类与 \\(n\\)；信道分区另计。</li><li>检测与超时是实现，不是模型本身。</li><li>出处：Lynch, <em>Distributed Algorithms</em>；Cristian, 1991。</li></ul>',7))])}const g=B(p,[["render",m]]);export{c as __pageData,g as default};
